template <>
struct Codec<SCError> {
  static constexpr std::uint64_t kMinSize = 4;
  static bool encode(const SCError&, Encoder&);
  static bool decode(SCError&, Decoder&);
  static bool gen(SCError&, XdrRng&, std::uint32_t);
  template <typename F>
  static void visit_fields(const SCError& v, F&& f) {
    f("type", v.t_);
    switch (v.t_) {
      case SCErrorType::SCE_CONTRACT:
        f("contractCode", std::get<0>(v.v_));
        return;
      case SCErrorType::SCE_WASM_VM:
      case SCErrorType::SCE_CONTEXT:
      case SCErrorType::SCE_STORAGE:
      case SCErrorType::SCE_OBJECT:
      case SCErrorType::SCE_CRYPTO:
      case SCErrorType::SCE_EVENTS:
      case SCErrorType::SCE_BUDGET:
      case SCErrorType::SCE_VALUE:
      case SCErrorType::SCE_AUTH:
        f("code", std::get<1>(v.v_));
        return;
      default: return;
    }
  }
};
